import {proofPrepayment} from './proof-payment-policy.mjs';
export const orderLabels={prepared:'Klar til PF',gateway_accepted:'Teknisk modtaget · afventer PF',confirmed:'Ordre bekræftet af PF',awaiting_proof:'Afventer korrektur fra PF',proof_received:'Korrektur klar',approval_pending_pf:'Kunden har godkendt',revision_requested:'Ændringer ønsket',approval_recorded:'Korrektur godkendt hos PF',processing:'PF behandler ordren',partially_shipped:'Delvist afsendt',shipped:'Afsendt',needs_attention:'Kræver afklaring',needs_reconciliation:'Afstem med PF',cancelled:'Annulleret'};
export const dateTime=value=>value&&!Number.isNaN(Date.parse(value))?new Date(value).toLocaleString('da-DK',{timeZone:'Europe/Copenhagen',day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'}):'—';
export function orderKind(order={},checkout={}){if(order.adminTest||checkout?.adminTest)return 'Intern test';if(order.isTest||order.gatewayPayload?.Header?.isTest)return 'PF-test';if(checkout?.adminPilot)return 'Rigtig testordre';return 'Kundeordre';}
export function shipmentNextStep(order,checkout,mails=[]){
 const tasks=[];
 if(checkout?.status==='authorized')tasks.push('Hæv betalingen, når alle varer på kundeordren er bekræftet afsendt.');
 else if(checkout?.status!=='paid')tasks.push('Afklar betaling: '+paymentLabel(checkout)+'.');
 const deliveries=order.shipment?.deliveries||[];
 if(!deliveries.length||deliveries.some(d=>!d.trackingDetails?.some(t=>t.trackingId&&t.trackingURL)))tasks.push('Kontrollér afsendelse og manglende trackingoplysninger.');
 if(!deliveries.length||deliveries.some(d=>!d.key||!mails.some(m=>m.orderId===order.id&&m.deliveryKey===d.key&&m.status==='sent')))tasks.push('Gennemgå forsendelsesmail og afsendelsesstatus under Historik.');
 return tasks.length?['Smerch',tasks.join(' ')]:['Afsluttet','Alle varer er afsendt, betalingen er hævet, og forsendelsesmails er sendt.'];
}
export function nextStep(order,checkout,mails=[]){if(order.adminTest||order.isTest||order.gatewayPayload?.Header?.isTest)return ['Test','Testordre · må ikke frigives til produktion.'];if(order.proofIntakeProblems?.length)return ['Smerch',order.proofIntakeProblems.join(' ')+' Se Historik eller Automatik og beskeder.'];if(checkout?.finance?.problems?.length)return ['Smerch',checkout.finance.problems.join(' ')+' Se Dokumenter → Fakturering, betaling og afstemning.'];if(order.status!=='cancelled'&&['authorization_expired','capture_reconciliation','payment_failed','needs_attention'].includes(checkout?.status))return ['Smerch','Afklar betaling: '+paymentLabel(checkout)+'.'];switch(order.status){case 'proof_received':return order.proof?.customer?['Kunden','Afventer kundens svar på korrekturen.']:['Smerch','Gennemgå korrekturen og send den til kunden.'];case 'approval_pending_pf':return order.decision?.delivery?.reference?['PF','Afventer PF’s bekræftelse af godkendelsen.']:['Smerch',proofPrepayment(checkout)?'Gennemgå kundens korrekturgodkendelse, godkend hævningen og send først svaret til PF efter bekræftet betaling.':'Godkend hos PF og registrér PF’s bekræftelse på ordren.'];case 'revision_requested':return order.decision?.delivery?.reference?['PF','Afventer en ny korrektur.']:['Smerch','Send kundens ændringer til PF.'];case 'partially_shipped':return ['PF','Delleverance registreret. Følg tracking og afvent de resterende varer.'];case 'approval_recorded':return ['PF','Korrektur godkendt hos PF. Produktionsstart er endnu ikke bekræftet. Afventer produktion og afsendelse.'];case 'processing':return ['PF','PF behandler ordren. Produktionsstart er ikke særskilt bekræftet. Afventer yderligere status eller afsendelse.'];case 'confirmed':return ['PF','Ordren er bekræftet hos PF. Produktionsstart er endnu ikke bekræftet.'];case 'shipped':return shipmentNextStep(order,checkout,mails);case 'cancelled':return ['Afsluttet','Ordren er annulleret.'];case 'prepared':return ['Smerch','Ordren er endnu ikke sendt til PF.'];case 'needs_attention':case 'needs_reconciliation':return ['Smerch','Kontrollér hændelsesloggen og afklar sagen med PF.'];case 'gateway_accepted':return ['PF','Teknisk kvittering modtaget. Afventer PF’s ordrebekræftelse.'];default:return ['PF','Afventer næste opdatering fra PF.'];}}
export function paymentLabel(checkout){if(!checkout)return 'Ingen betaling tilknyttet';if(checkout.paymentProvider==='bank_transfer')return checkout.status==='paid'?'Bankbetaling modtaget':checkout.status==='awaiting_bank_payment'?'Afventer faktura / bankbetaling':checkout.status;return {authorized:'Reserveret · ikke hævet',paid:'Hævet',partially_paid:'Delvist hævet',cancelled:'Annulleret',needs_attention:'Betaling kræver afklaring',prepared:'Betaling klargjort',payment_setup:'Betaling oprettes',payment_setup_uncertain:'Oprettelse af betaling skal afklares',payment_failed:'Betaling mislykkedes',awaiting_payment:'Afventer betaling',authorization_expired:'Reservation udløbet',capture_reconciliation:'Hævning skal afstemmes',expired:'Betalingslink udløbet'}[checkout.status]||checkout.status;}
export const eventLabels={staff_proof_payment_approved:'Smerch har godkendt korrekturversionen og betalingen',smerch_review_required:'Afventer Smerchs gennemgang før PF',smerch_review_approved:'Ordren er gennemgået og godkendt af Smerch',customer_proof_published:'Korrektur sendt til kundegodkendelse',customer_approved:'Kunden har godkendt korrekturen',smerch_approved:'Smerch har registreret godkendelse',revision_requested:'Ændringer ønsket',approval_sent_to_pf:'Godkendelse sendt til PF',revision_sent_to_pf:'Ændringsønske sendt til PF',external_approval_recorded:'Korrekturgodkendelse hos PF registreret',prepared:'Ordre klargjort',submitting:'Sender til PF',gateway_accepted:'Teknisk kvittering fra PF',pf_confirmation:'PF-ordrebekræftelse modtaget',pf_status:'Status opdateret fra PF',proof_received:'Korrektur modtaget',proof_published:'Korrektur sendt til kunden',customer_decision:'Kunden har svaret',approval_delivery:'Beslutning sendt til PF',external_approval:'PF har bekræftet godkendelsen',shipped:'Afsendelse registreret'};

// A real pilot checkout belongs in operations; only non-production tests are hidden.
export function isTestOrder(order={},checkout={}){return ['Intern test','PF-test'].includes(orderKind(order,checkout));}
